@use "./base.scss";

@media all and (min-width: 1200px) {
  .page {
    width: 96vw;
    max-width: 2800px;
  }

  .page > #quartz-body {
    grid-template-columns:
      clamp(16rem, 19vw, 24rem)
      minmax(0, 1fr)
      clamp(14rem, 17vw, 20rem);
  }

  .page > #quartz-body > .center {
    min-width: 0;
  }
}
